// Generated by Skyramp — shared helpers for the field-reorder UI tests.
//
// These helpers drive the "Fields & Layout" list in Settings > Data Model, rendered by
// app/src/modules/settings/routes/data-model/fields/components/fields-management.vue.
import type { Page } from '@playwright/test';

export const ADMIN_EMAIL = 'admin@example.com';
export const ADMIN_PASSWORD = 'admin';

/** Unique per run so the create-collection step never collides on re-runs. */
export function uniqueCollectionName(prefix: string): string {
	return `${prefix}_${Date.now().toString(36)}${Math.floor(Math.random() * 1e4)}`;
}

/**
 * Wait until every running CSS transition/animation has finished.
 *
 * Directus dialogs and drawers slide in behind a full-screen `.overlay`; clicking a
 * control mid-transition fails with "overlay intercepts pointer events". This waits on
 * the real animation state rather than sleeping for a fixed interval.
 */
export async function waitForAnimations(page: Page): Promise<void> {
	await page
		.waitForFunction(() => document.getAnimations().every((a) => a.playState !== 'running'), undefined, {
			timeout: 15000,
		})
		.catch(() => {
			/* best effort — never fail a test on an animation that loops */
		});
}

/**
 * Dismiss the BSL "You have not set a project owner" dialog.
 *
 * It re-mounts on every full page load (not just at login) and holds a full-screen
 * active overlay that swallows clicks meant for the page underneath.
 *
 * Call this only on a page with no drawer open: while the create-collection drawer is
 * also mounted, the dialog does not detach on dismiss and its overlay keeps blocking.
 */
export async function dismissOwnerDialog(page: Page): Promise<void> {
	const remindLater = page.getByRole('button', { name: 'Remind Later' });

	// NOTE: locator.isVisible() does not retry, so it would race the dialog's mount and
	// report false while it is still rendering. waitFor() retries.
	const appeared = await remindLater
		.waitFor({ state: 'visible', timeout: 15000 })
		.then(() => true)
		.catch(() => false);

	if (!appeared) return;

	await waitForAnimations(page);
	await remindLater.click();
	await remindLater.waitFor({ state: 'detached', timeout: 15000 });
	await waitForAnimations(page);
}

/** Log in through the real sign-in form and clear the project-owner dialog. */
export async function login(page: Page, baseUrl: string): Promise<void> {
	await page.goto(baseUrl);
	await page.getByRole('textbox', { name: 'Email' }).fill(ADMIN_EMAIL);
	await page.getByRole('textbox', { name: 'Password' }).fill(ADMIN_PASSWORD);
	await Promise.all([
		page.waitForResponse((r) => r.url().includes('/auth/login')),
		page.getByRole('button', { name: 'Sign In' }).click(),
	]);

	// Directus restores the last visited route after login, which may be a drawer route.
	// Land on a neutral page so the owner dialog can actually be dismissed.
	await page.goto(`${baseUrl}/admin/content`);
	await dismissOwnerDialog(page);
}

/** Open a data-model page by full reload, clearing the owner dialog it re-mounts. */
export async function reloadDataModelPage(page: Page, baseUrl: string, collection: string): Promise<void> {
	await page.goto(`${baseUrl}/admin/settings/data-model/${collection}`);
	await dismissOwnerDialog(page);
	await waitForFieldsLoaded(page, 3);
}

/**
 * Create a collection with the `status` and `date_created` optional fields enabled,
 * producing three reorderable fields (id, status, date_created).
 *
 * Navigation is in-app (SPA) rather than page.goto: a full reload re-mounts the
 * project-owner dialog, whose overlay then blocks the wizard.
 */
export async function createCollection(page: Page, baseUrl: string, prefix: string): Promise<string> {
	const collection = uniqueCollectionName(prefix);

	await page.getByRole('link', { name: 'settings' }).click();
	await page.waitForURL('**/admin/settings**');
	await page.getByRole('link', { name: 'Data Model' }).first().click();
	await page.waitForURL('**/admin/settings/data-model**');

	// Header "+" opens the Create Collection wizard; present whether or not any exist.
	await page.getByRole('link', { name: 'add' }).first().click();
	await waitForAnimations(page);

	await page.getByRole('textbox', { name: 'A unique table name...' }).fill(collection);
	await page.getByRole('button', { name: 'arrow_forward' }).click();

	// Optional System Fields step: enable Status and Created On.
	await waitForAnimations(page);
	await page.getByRole('checkbox', { name: 'check_box_outline_blank' }).nth(0).click();
	await page.getByRole('checkbox', { name: 'check_box_outline_blank' }).nth(1).click();

	await Promise.all([
		page.waitForResponse((r) => r.url().includes('/collections') && r.request().method() === 'POST'),
		page.getByRole('button', { name: 'check' }).click(),
	]);

	await page.waitForURL(`${baseUrl}/admin/settings/data-model/${collection}`);
	await waitForFieldsLoaded(page, 3);

	return collection;
}

/** Locator for the field-name labels in the draggable Fields & Layout list. */
export function fieldNameLocator(page: Page) {
	return page.locator('.field-grid .field-select .name');
}

/** Current field order as trimmed names, top to bottom. */
export async function fieldOrder(page: Page): Promise<string[]> {
	return (await fieldNameLocator(page).allTextContents()).map((t) => t.trim());
}

/** Wait until the Fields & Layout list has rendered `count` rows. */
export async function waitForFieldsLoaded(page: Page, count: number): Promise<void> {
	await fieldNameLocator(page)
		.nth(count - 1)
		.waitFor({ state: 'visible', timeout: 15000 });
}

/**
 * Drag the field at `fromIndex` onto the row at `toIndex` using that row's drag handle.
 *
 * vuedraggable runs here with `force-fallback: true`, so the reorder is driven by real
 * mouse events rather than the HTML5 drag-and-drop API. Coordinates are read from the
 * live DOM instead of being hardcoded so the drag survives layout changes.
 */
export async function dragField(page: Page, fromIndex: number, toIndex: number): Promise<void> {
	const handles = await page.evaluate(() =>
		[...document.querySelectorAll('.field-grid .drag-handle')].map((h) => {
			const r = h.getBoundingClientRect();
			return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
		}),
	);

	const from = handles[fromIndex];
	const to = handles[toIndex];
	if (!from || !to) throw new Error(`drag handle missing (from=${fromIndex}, to=${toIndex}, have=${handles.length})`);

	// Overshoot slightly past the target row's midpoint so Sortable commits the swap.
	const endY = to.y + (fromIndex > toIndex ? -7 : 7);

	await page.mouse.move(from.x, from.y);
	await page.mouse.down();
	await page.mouse.move(from.x, endY, { steps: 25 });
	await page.mouse.up();
}

/** Delete a collection from a second tab, simulating another admin removing it concurrently. */
export async function deleteCollectionInOtherTab(page: Page, baseUrl: string, collection: string): Promise<void> {
	const other = await page.context().newPage();
	await other.goto(`${baseUrl}/admin/settings/data-model/${collection}`);
	await dismissOwnerDialog(other);
	await other.getByRole('button', { name: 'delete' }).click();
	await waitForAnimations(other);
	await Promise.all([
		other.waitForResponse((r) => r.url().includes(`/collections/${collection}`) && r.request().method() === 'DELETE'),
		other.getByRole('button', { name: 'Delete', exact: true }).click(),
	]);
	await other.close();
}

/**
 * Map a PATCH /fields/{collection} response body to `{ fieldName: sort }`.
 *
 * Directus replies with `{ data: [{ field, meta: { sort } }, ...] }`. Keying by field
 * name keeps assertions independent of the array ordering of the response.
 */
export function sortByField(body: { data: Array<{ field: string; meta: { sort: number } }> }): Record<string, number> {
	return Object.fromEntries(body.data.map((f) => [f.field, f.meta.sort]));
}
